            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0xF557502E02E2E44BULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0xAFEFA53CEBB6D3BBULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x85B9D6E55268F8D9ULL), 41U);
