            aScatter = (RotL64(aPrevious, 5U) ^ RotL64(aCarry, 22U)) ^ (RotL64(aCross, 39U) + RotL64(aIngress, 53U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterJ = ((aWandererD + RotL64(aCross, 47U)) + 0x39D7BE4932A8BF08ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aPrevious, 39U)) + 0x141BB9180D52A419ULL;
            aOrbiterA = ((aWandererA + RotL64(aScatter, 10U)) + 0x5E604F151A7AC815ULL) + aTwistOrbiterAssignSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterF = (aWandererK + RotL64(aIngress, 43U)) + 0x698472815698D774ULL;
            aOrbiterG = ((aWandererF + RotL64(aScatter, 5U)) + RotL64(aCarry, 39U)) + 0x2A924B1B87C1BC3BULL;
            aOrbiterH = ((aWandererH + RotL64(aPrevious, 51U)) + RotL64(aCarry, 51U)) + 0xB0BAACCE77BA50C1ULL;
            aOrbiterC = (aWandererJ + RotL64(aIngress, 21U)) + 0x1F29F7A54A87C6CBULL;
            aOrbiterD = (aWandererC + RotL64(aCross, 30U)) + 0xFA0E69CF38E64F2AULL;
            aOrbiterK = ((aWandererB + RotL64(aIngress, 35U)) + RotL64(aCarry, 29U)) + 0xE756CD1E67F3E5FDULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xAB1E0ABBCCEC2BF1ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x5D5030B4A1AEB379ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1EA9A3204615B6D3ULL), 19U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x0F3AD5F6128F52E3ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x4D3F34F9F019F267ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0E7190D0EA93530FULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xD6C9B269469A849DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x096B922972A1B843ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xBFA09329BE59653BULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xE41659F611CC2FA5ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x173F25878DC5CC3FULL;
            aOrbiterD = RotL64((aOrbiterD * 0x904F75385332D32DULL), 39U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x7826176942EE5095ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x414CAFB0981FC749ULL;
