            //
            aOrbiterD = ((aWandererG + RotL64(aIngress, 53U)) + 0x7E290D278B2A953DULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aScatter, 3U)) + 0x4507DB03220C0BCCULL;
            aOrbiterA = (aWandererD + RotL64(aCross, 60U)) + 0x3B26C46B69BF92D1ULL;
            aOrbiterH = ((aWandererH + RotL64(aPrevious, 27U)) + 0xB4B4AD8ED1177C78ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aIngress, 13U)) + RotL64(aCarry, 47U)) + 0xC7E7AE728AE045D3ULL;
            aOrbiterJ = (aWandererA + RotL64(aScatter, 41U)) + 0x7862AA22918311E5ULL;
            aOrbiterC = (aWandererK + RotL64(aCross, 37U)) + 0xB0548ED73F8312B5ULL;
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 48U)) + RotL64(aCarry, 13U)) + 0x87106D07927C78DEULL;
            aOrbiterF = ((aWandererJ + RotL64(aCross, 23U)) + RotL64(aCarry, 37U)) + 0x4DEA9CBDAB2A35B1ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x13FB95C270F0AA6DULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0x296EBF7825F83C37ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x6052E9A09EF11A69ULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x350B0671C453DAB3ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x90D16857B78CDDC5ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x94A74B80E1B74D91ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x9901A96BAF056E97ULL;
