            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0x4A930AF2376EEF91ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x50E4110363A51527ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8ECD449B98926A4DULL), 57U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterC) + 0x4AEED63E1A0CC646ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xBA4ED8C90D39890AULL;
