            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x05847A6841E15152ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x0716716953264A54ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x14D3778315FA17AFULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xEF82C85442454E57ULL;
