            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0xA77CEE1C3652FAF3ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x69789176ADB62D7AULL;
