            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 53U) + RotL64(aCarry, 39U)) + (RotL64(aCross, 23U) ^ RotL64(aIngress, 10U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = (aWandererE + RotL64(aPrevious, 43U)) + 0x024DDB494416D9B3ULL;
            aOrbiterK = ((aWandererG + RotL64(aIngress, 29U)) + 0x6874157D96D67D78ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterF = ((aWandererC + RotL64(aScatter, 5U)) + RotL64(aCarry, 19U)) + 0x1366197EBD760B61ULL;
            aOrbiterG = (((aWandererI + RotL64(aCross, 23U)) + RotL64(aCarry, 41U)) + 0x6965C2861C62978FULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterC = ((aWandererD + RotL64(aIngress, 11U)) + RotL64(aCarry, 53U)) + 0x583AD99BBD7D7EA8ULL;
            aOrbiterI = (aWandererB + RotL64(aPrevious, 60U)) + 0x4C6B944F9626CCC4ULL;
            aOrbiterH = (aWandererF + RotL64(aCross, 35U)) + 0xF4616D48651D1A30ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0x79AC7D1CDFAB42F5ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterB) ^ 0x8A0A89649D1608F2ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x921839671AFEF763ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xDBD82FAA741319FCULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xD7D5B34F21BC2FA2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x90F31F6BD08C3DCDULL), 37U);
