            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0xE5F389AEABE62091ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xD6B49F6189C41DA0ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xFAFC286FE86C7D2BULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x6D3072C589919D61ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x0B1DC61CD896AB9FULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xF8916A7B4E0D73E3ULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x9D42C0F81EE99702ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x5F69261393F82322ULL;
