            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x6547A7F7EE2BBE3DULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x8C821B4DC9270339ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x7E617AE96A21BECBULL), 3U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 27U);
