            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterF, 5U));
            aIngress = aIngress + RotL64(aOrbiterI, 11U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ (((RotL64(aIngress, 19U) + RotL64(aOrbiterB, 21U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltA[((aIndex + 14U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 13U) + RotL64(aOrbiterC, 58U)) + aOrbiterI) + aKeyRotateAWandererUpdateSaltD[((aIndex + 25U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 53U) + RotL64(aOrbiterI, 13U)) + aOrbiterB);
