            aIngress ^= (RotL64(aShadowLaneC[((aIndex + 8603U)) & S_BLOCK1], 51U) ^ RotL64(aKeyRowReadB[((aIndex + 15622U)) & W_KEY1], 43U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 12856U)) & S_BLOCK1], 19U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 9398U)) & S_BLOCK1], 39U));
            aCross ^= (RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 12974U)) & S_BLOCK1], 28U) ^ RotL64(aShadowLaneA[((aIndex + 16368U)) & S_BLOCK1], 51U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 3U) + RotL64(aCarry, 51U)) ^ (RotL64(aIngress, 38U) ^ RotL64(aCross, 21U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = (aWandererB + RotL64(aPrevious, 29U)) + 0xD07A270CA021BC25ULL;
            aOrbiterH = (aWandererG + RotL64(aCross, 37U)) + 0x35850F45B61B721FULL;
            aOrbiterA = ((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 51U)) + 0x8267DFA199F430BFULL;
            aOrbiterG = (aWandererI + RotL64(aScatter, 46U)) + 0xE5EDDA077836118FULL;
            aOrbiterE = (aWandererC + RotL64(aPrevious, 57U)) + 0xCA9CF5D182EF0E1AULL;
            aOrbiterD = (((aWandererF + RotL64(aScatter, 13U)) + RotL64(aCarry, 5U)) + 0xC55EAEF3BBF496F7ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterF = (((aWandererJ + RotL64(aCross, 21U)) + RotL64(aCarry, 27U)) + 0xAF47BBA09A9A9DDFULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 21U)) & S_SALT1];
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x2439615271685D10ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x1654E5A880A5E53CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x694F19F5C22689CDULL), 53U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0x235586B2523391F0ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x9E5DF8F22A924530ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xEE7993E6C1E7371DULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0xB29A5820FA4DC6BEULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x0A50507B8C65B396ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xEB9372F592A9A59BULL), 19U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x39F6EF85D9E3EA30ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x1B1F717C78564B5CULL;
            aOrbiterD = RotL64((aOrbiterD * 0xDB1FC696D6D04721ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x9BBD573D81D9D41EULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xB91A4EF46F11556CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0869AEFE274CF62DULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x4D86EE05021C98B9ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xB71076228A068508ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x22CA6D073D143473ULL), 47U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0x650DAC63F35AD5F6ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x88B6B272F4E06302ULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x776EC3D84E31E24DULL), 37U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterJ, 57U);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterD, 13U));
            aIngress = aIngress + (RotL64(aOrbiterG, 23U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterF, 4U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterG, 57U)) + aOrbiterJ);
