            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x7B420F217C779FACULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xACD04BB241FA8BE9ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x345DC3382AFAC119ULL), 11U);
