            aOrbiterE = (aWandererB + RotL64(aIngress, 18U)) + 0xF721258D6B2D83D9ULL;
            aOrbiterB = ((aWandererG + RotL64(aCross, 11U)) + RotL64(aCarry, 51U)) + 0xA95AA5CF09EDC1F0ULL;
            aOrbiterH = ((aWandererA + RotL64(aScatter, 27U)) + 0x781DB1DE767230F8ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
