            aWandererE = aWandererE ^ (((RotL64(aCross, 51U) + RotL64(aOrbiterH, 19U)) + aOrbiterJ) + aKeyRotateAWandererUpdateSaltA[((aIndex + 3U)) & S_SALT1]);
